/**
 * Compiled wallet contract code as BOC hex strings.
 *
 * These are the standard FunC wallet contracts compiled and serialized
 * as Bag-of-Cells (BOC) hex. They are the canonical code cells used to
 * compute deterministic wallet addresses on the TOS blockchain.
 *
 * Sources: standard wallet contract code cells.
 */

/**
 * Wallet V3 revision 2 compiled code (BOC hex).
 *
 * Data layout: seqno:uint32 walletId:uint32 publicKey:bits256
 * Signing message: walletId:uint32 validUntil:uint32 seqno:uint32 [mode:uint8 message:^Cell]*
 */
export const WALLET_V3R2_CODE =
  "B5EE9C724101010100710000DEFF0020DD2082014C97BA218201339CBAB19F71B0ED44D0D31FD31F31D70BFFE304E0A4F2608308D71820D31FD31FD31FF82313BBF263ED44D0D31FD31FD3FFD15132BAF2A15144BAF2A204F901541055F910F2A3F8009320D74A96D307D402FB00E8D101A4C8CB1FCB1FCBFFC9ED5410BD6DAD";

/**
 * Wallet V4 revision 2 compiled code (BOC hex).
 *
 * Data layout: seqno:uint32 walletId:uint32 publicKey:bits256 plugins:dict
 * Signing message: walletId:uint32 validUntil:uint32 seqno:uint32 op:uint8 [mode:uint8 message:^Cell]*
 * op=0: simple transfer, op=1: deploy+install plugin, op=2: install plugin, op=3: remove plugin
 */
export const WALLET_V4R2_CODE =
  "";

/**
 * Wallet V5 revision 1 compiled code (BOC hex).
 *
 * V5 (W5) uses a different authentication structure supporting both
 * internal and external messages, extensions, and actions-based transfers.
 *
 * Data layout: isSignatureAllowed:bool seqno:uint32 walletId:uint32 publicKey:bits256 extensions:dict
 * Signing message (external): walletId:uint32 validUntil:uint32 seqno:uint32 actions...
 * The walletId in V5 encodes: networkGlobalId (int32) + workchain (int8) + walletVersion (uint8) + subwalletNumber (uint32)
 */
export const WALLET_V5R1_CODE =
  "";

/**
 * Highload Wallet V2 compiled code (BOC hex).
 *
 * Supports sending up to 254 messages in a single external message
 * using a dictionary-based message storage.
 *
 * Data layout: walletId:uint32 lastCleaned:uint64 publicKey:bits256 oldQueries:dict
 * Signing message: walletId:uint32 queryId:uint64 messages:dict(uint16->Cell)
 */
export const HIGHLOAD_V2_CODE =
  "B5EE9C7241010101005F0000BAFF0020DD2082014C97BA218201339CBAB19C71B0ED44D0D31FD70BFFE304E0A4F260810200D71820D70B1FED44D0D31FD3FFD15112BAF2A122F901541044F910F2A2F80001D31F3120D74A96D307D402FB00DED1A4C8CB1FCBFFC9ED54B5B86E42";
